import sys

def longest_common_prefix_brute(strs):
    if not strs:
        return ""
    prefix = strs[0]
    for s in strs[1:]:
        i = 0
        while i < len(prefix) and i < len(s) and prefix[i] == s[i]:
            i += 1
        prefix = prefix[:i]
        if not prefix:
            break
    return prefix

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if not data:
        sys.exit(0)
    n = int(data[0])
    strs = [data[i + 1].rstrip('\n') for i in range(n)]
    print(longest_common_prefix_brute(strs))

import sys

def longest_common_prefix_opt(strs):
    if not strs:
        return ""
    for i, ch in enumerate(strs[0]):
        for s in strs[1:]:
            if i >= len(s) or s[i] != ch:
                return strs[0][:i]
    return strs[0]

