import sys

def is_common_prefix(strs, length):
    base = strs[0][:length]
    for s in strs[1:]:
        if not s.startswith(base):
            return False
    return True

def longest_common_prefix_best(strs):
    if not strs:
        return ""
    lo, hi = 0, min(len(s) for s in strs)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if is_common_prefix(strs, mid):
            lo = mid
        else:
            hi = mid - 1
    return strs[0][:lo]

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if not data:
        sys.exit(0)
    n = int(data[0])
    strs = [data[i + 1].rstrip('\n') for i in range(n)]
    print(longest_common_prefix_best(strs))
